func TestInit_RoutesBareSlogToLogFile(t *testing.T) {
	tmpDir := t.TempDir()
	t.Chdir(tmpDir)

	initGitRepo(t, tmpDir)

	if err := Init(context.Background(), testSessionID); err != nil {
		t.Fatalf("Init() error = %v", err)
	}

	// Bare slog.Warn — this is how the redact package logs.
	slog.Warn("bare-slog-warning", slog.String("component", "redaction"), slog.String("rule", "test-rule"))

	// Close flushes the buffered writer.
	Close()

	content, err := os.ReadFile(testLogFilePath(tmpDir))
	if err != nil {
		t.Fatalf("read log file: %v", err)
	}
	if !strings.Contains(string(content), "bare-slog-warning") {
		t.Errorf("expected bare slog.Warn to land in entire.log; content: %s", content)
	}
	if !strings.Contains(string(content), `"component":"redaction"`) {
		t.Errorf("expected redaction component attr in entire.log; content: %s", content)
	}
