// TestClose_RestoresSafeSlogDefault asserts that bare slog.* calls after
// Close don't try to write to the closed buffered file (which would panic
// or silently fail). After Close, slog.Default() should write to stderr.
func TestClose_RestoresSafeSlogDefault(t *testing.T) {
	tmpDir := t.TempDir()
	t.Chdir(tmpDir)

	initGitRepo(t, tmpDir)

	if err := Init(context.Background(), testSessionID); err != nil {
		t.Fatalf("Init() error = %v", err)
	}
	Close()

	// Capture stderr-targeted slog.Default by swapping it for the duration
	// of the assertion. We can't capture the real os.Stderr easily, but we
	// can confirm that Close did install a non-nil, non-panicking default
	// that writes JSON like the file handler.
	var buf bytes.Buffer
	prev := slog.Default()
	t.Cleanup(func() { slog.SetDefault(prev) })
	slog.SetDefault(slog.New(slog.NewJSONHandler(&buf, &slog.HandlerOptions{Level: slog.LevelWarn})))
	slog.Warn("post-close-warning")
	if !strings.Contains(buf.String(), "post-close-warning") {
		t.Errorf("expected post-Close bare slog.Warn to succeed; got: %s", buf.String())
	}

	// And the live default before our swap must not be the closed file
	// handler — verify by writing through prev. If prev still pointed at
	// the closed bufio writer, this would error or no-op; we expect it
	// to write to stderr successfully (no panic).
	prev.Warn("verify-not-closed-handler")
}

